-- Owners whose own pages say American, promoted to ACTIVE (checked 2026-10-11):
-- 317 Mahj Collective (Indianapolis): its own Linktree reads "American Mahjong lessons and events in the 317".
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-10-11', "updatedAt" = CURRENT_TIMESTAMP WHERE "name" = '317 Mahj Collective' AND "cityId" = (SELECT id FROM City WHERE name = 'Indianapolis' AND state = 'IN');
-- The Traveling Mahj (St. Louis): its own page says play follows "NMJL gameplay rules".
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-10-11', "updatedAt" = CURRENT_TIMESTAMP WHERE "name" = 'The Traveling Mahj' AND "cityId" = (SELECT id FROM City WHERE name = 'St. Louis' AND state = 'MO');
-- Mahjong Social Club Jax: its Open Play Events page lists these sessions as open for registration (no year printed; all are upcoming dates on a live booking page).
UPDATE "Event" SET "status" = 'ACTIVE', "startTime" = '17:30', "price" = 23.3, "lastVerifiedAt" = '2026-10-11', "updatedAt" = CURRENT_TIMESTAMP WHERE "name" = 'Open Play @ Trattoria Di Bernardone' AND substr("eventDate", 1, 10) IN ('2026-10-15', '2026-11-04') AND "clubId" = (SELECT id FROM Club WHERE name = 'Mahjong Social Club Jax');
UPDATE "Event" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-10-11', "updatedAt" = CURRENT_TIMESTAMP WHERE "name" = 'Open Play @ Gaa Cafe' AND substr("eventDate", 1, 10) = '2026-11-20' AND "clubId" = (SELECT id FROM Club WHERE name = 'Mahjong Social Club Jax');
-- Housekeeping: events already past their date are no longer ACTIVE.
UPDATE "Event" SET "status" = 'INACTIVE', "updatedAt" = CURRENT_TIMESTAMP WHERE "status" = 'ACTIVE' AND "eventDate" < '2026-10-11 00:00:00';
